mkdir -p /tmp/scripts && cat > /tmp/scripts/t.js <<'E'
const B='<cwd>/servers/log-triage/';
const {list}=require(B+'list.js'),{read}=require(B+'read.js'),{redact}=require(B+'redact.js'),{cluster}=require(B+'cluster.js');
(async()=>{
const l=await list({dir:'/data/f2x100'});console.log(JSON.stringify(l));
let all=[];
for(const f of l.files){const r=await read({dir:'/data/f2x100',name:f.name,maxBytes:16777216});console.log(f.name,r.lineCount,r.truncated);all.push(...r.lines);}
const rd=await redact({lines:all});console.log(JSON.stringify(rd.counts));
const c=await cluster({lines:rd.lines,topClusters:10});console.log(JSON.stringify(c,null,1));
})();
E
node /tmp/scripts/t.js

